function TrainingDialog({ onClose }: { onClose: () => void }) {
  const [section, setSection] = useState<"weeks" | "exercises" | "projects" | "resources">("weeks");
  const tabs = [{ id: "weeks", label: "Calendrier" }, { id: "exercises", label: "Exercices" }, { id: "projects", label: "Projets" }, { id: "resources", label: "Ressources" }] as const;
  return <div className="fixed inset-0 z-50 grid place-items-center overflow-y-auto bg-slate-950/60 p-3 sm:p-6" onClick={onClose}><section role="dialog" aria-modal="true" aria-labelledby="training-title" onClick={event => event.stopPropagation()} className="max-h-[calc(100dvh_-_1.5rem)] w-full max-w-5xl overflow-y-auto rounded-3xl bg-white p-5 shadow-2xl sm:p-7 dark:bg-[#191a28]"><div className="mb-5 flex items-start justify-between gap-4"><div><p className="mb-1 text-xs font-bold uppercase tracking-widest text-violet-500">Parcours de formation</p><h2 id="training-title" className="text-2xl font-black text-slate-900 dark:text-white">Ingénieur en IA générative</h2><p className="mt-1 text-sm text-slate-500 dark:text-slate-300">24 semaines · 10 heures par semaine · calendrier, exercices, projets et ressources</p></div><button aria-label="Fermer la formation" onClick={onClose} className="rounded-lg p-1 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800"><X size={20}/></button></div><div className="mb-5 flex flex-wrap gap-2" role="tablist" aria-label="Sections du parcours">{tabs.map(tab => <button key={tab.id} role="tab" aria-selected={section === tab.id} onClick={() => setSection(tab.id)} className={`rounded-xl px-4 py-2 text-sm font-bold ${section === tab.id ? "bg-violet-600 text-white" : "bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-200"}`}>{tab.label}</button>)}</div>{section === "weeks" && <div className="space-y-3">{trainingData.weeks.map(item => <article key={item.week} className="rounded-2xl border border-slate-100 p-4 dark:border-slate-700"><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-xs font-bold uppercase tracking-wide text-violet-500">Semaine {item.week} · {item.phase}</p><h3 className="mt-1 font-black text-slate-900 dark:text-white">{item.theme}</h3></div><span className="rounded-full bg-blue-50 px-3 py-1 text-xs font-bold text-blue-600">{item.hours} h</span></div><p className="mt-2 text-sm text-slate-500 dark:text-slate-300">Ressource : {item.resource}</p><p className="mt-1 text-sm text-slate-600 dark:text-slate-200">Livrable : {item.deliverable}</p></article>)}</div>}{section === "exercises" && <div className="space-y-3">{trainingData.exercises.map(item => <article key={item.id} className="rounded-2xl border border-slate-100 p-4 dark:border-slate-700"><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-xs font-bold uppercase tracking-wide text-violet-500">Semaine {item.week} · {item.id} · {item.phase}</p><h3 className="mt-1 font-black text-slate-900 dark:text-white">{item.title}</h3></div><span className="rounded-full bg-blue-50 px-3 py-1 text-xs font-bold text-blue-600">{item.hours} h</span></div><p className="mt-2 whitespace-pre-line text-sm text-slate-600 dark:text-slate-200">{item.instructions}</p><p className="mt-2 text-sm text-slate-500 dark:text-slate-300">Livrable : {item.deliverable}</p><p className="mt-1 text-sm text-slate-500 dark:text-slate-300">Critère : {item.criteria}</p></article>)}</div>}{section === "projects" && <div className="grid gap-3 sm:grid-cols-2">{trainingData.projects.map(item => <article key={item.name} className="rounded-2xl border border-slate-100 p-4 dark:border-slate-700"><p className="text-xs font-bold uppercase tracking-wide text-violet-500">{item.name} · semaine {item.weeks}</p><h3 className="mt-1 font-black text-slate-900 dark:text-white">{item.title}</h3><p className="mt-2 text-sm text-slate-500 dark:text-slate-300">Livrables : {item.deliverable}</p><p className="mt-1 text-sm text-slate-500 dark:text-slate-300">Critère : {item.criteria}</p></article>)}</div>}{section === "resources" && <div className="grid gap-3 sm:grid-cols-2">{trainingData.resources.map(item => <a key={item.url} href={item.url} target="_blank" rel="noreferrer" className="rounded-2xl border border-slate-100 p-4 transition hover:border-violet-300 hover:bg-violet-50/50 dark:border-slate-700 dark:hover:bg-slate-800"><h3 className="font-bold text-slate-900 dark:text-white">{item.name}</h3><p className="mt-1 text-xs text-slate-500 dark:text-slate-300">{item.language} · {item.cost}</p><p className="mt-2 break-all text-xs font-semibold text-violet-600">{item.url}</p></a>)}</div>}</section></div>;
}

function reportRange(period: ReportPeriod, reference: Date, offset = 0) {
  const today = new Date(reference.getFullYear(), reference.getMonth(), reference.getDate());
  let start: Date;
  let end: Date;
  if (period === "week") {
    start = new Date(today);
    start.setDate(start.getDate() - ((start.getDay() + 6) % 7) + offset * 7);
    end = new Date(start);
    end.setDate(end.getDate() + 6);
  } else if (period === "month") {
    start = new Date(today.getFullYear(), today.getMonth() + offset, 1);
    end = new Date(start.getFullYear(), start.getMonth() + 1, 0);
  } else {
    start = new Date(today.getFullYear(), Math.floor(today.getMonth() / 3) * 3 + offset * 3, 1);
    end = new Date(start.getFullYear(), start.getMonth() + 3, 0);
  }
  const title = period === "week"
    ? `${start.toLocaleDateString("fr-FR", { day: "numeric", month: "short" })} – ${end.toLocaleDateString("fr-FR", { day: "numeric", month: "short", year: "numeric" })}`
    : period === "month"
      ? start.toLocaleDateString("fr-FR", { month: "long", year: "numeric" })
      : `${Math.floor(start.getMonth() / 3) + 1}e trimestre ${start.getFullYear()}`;
  return { start: dateKey(start), end: dateKey(end), title };
}
function ReportsDialog({ entries, now, onClose }: { entries: ProductivityEntry[]; now: Date; onClose: () => void }) {
  const [period, setPeriod] = useState<ReportPeriod>("week");
  const range = reportRange(period, now);
  const previousRange = reportRange(period, now, -1);
  const periodEntries = entries.filter(entry => entry.date >= range.start && entry.date <= range.end);
  const previousTotal = entries.filter(entry => entry.date >= previousRange.start && entry.date <= previousRange.end).reduce((sum, entry) => sum + entry.count, 0);
  const total = periodEntries.reduce((sum, entry) => sum + entry.count, 0);
  const taskTotal = periodEntries.filter(entry => entry.kind === "task").reduce((sum, entry) => sum + entry.count, 0);
  const habitTotal = periodEntries.filter(entry => entry.kind === "habit").reduce((sum, entry) => sum + entry.count, 0);
  const activeDays = new Set(periodEntries.map(entry => entry.date)).size;
  const change = previousTotal ? Math.round((total - previousTotal) / previousTotal * 100) : null;
  const sortedEntries = [...periodEntries].sort((a, b) => b.date.localeCompare(a.date));
  return <div className="fixed inset-0 z-50 grid place-items-center overflow-y-auto bg-slate-950/50 p-3 sm:p-5" onClick={onClose}><section role="dialog" aria-modal="true" aria-labelledby="reports-title" onClick={event => event.stopPropagation()} className="max-h-[calc(100dvh_-_1.5rem)] w-full max-w-2xl overflow-y-auto rounded-3xl bg-white p-5 shadow-2xl sm:p-7 dark:bg-[#191a28]"><div className="mb-5 flex items-start justify-between gap-4"><div><p className="mb-1 text-xs font-bold uppercase tracking-widest text-violet-500">Bilan d’activité</p><h2 id="reports-title" className="text-xl font-black text-slate-900 dark:text-white">Rapport {period === "week" ? "de la semaine" : period === "month" ? "du mois" : "trimestriel"}</h2></div><button aria-label="Fermer les rapports" onClick={onClose} className="rounded-lg p-1 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800"><X size={20}/></button></div><div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><select aria-label="Période du rapport" value={period} onChange={event => setPeriod(event.target.value as ReportPeriod)} className="rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm font-bold text-slate-700 dark:border-slate-700 dark:bg-slate-800 dark:text-white"><option value="week">Cette semaine</option><option value="month">Ce mois</option><option value="quarter">Ce trimestre</option></select><p className="text-sm font-semibold capitalize text-slate-500 dark:text-slate-300">{range.title}</p></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-4"><ReportMetric label="Activités réalisées" value={total} detail={change === null ? "Pas de période précédente" : `${change > 0 ? "+" : ""}${change}% vs période précédente`} color="violet"/><ReportMetric label="Tâches terminées" value={taskTotal} detail="Tâches cochées" color="blue"/><ReportMetric label="Habitudes validées" value={habitTotal} detail="Habitudes cochées" color="green"/><ReportMetric label="Jours actifs" value={activeDays} detail={period === "week" ? "sur 7 jours" : period === "month" ? "ce mois-ci" : "ce trimestre"} color="orange"/></div><div className="mt-5 rounded-2xl bg-slate-50 p-4 dark:bg-slate-800/70"><p className="text-sm font-bold text-slate-800 dark:text-white">Comparaison avec la période précédente</p><p className="mt-1 text-sm text-slate-500 dark:text-slate-300">{change === null ? "La comparaison sera disponible dès qu’une activité aura été enregistrée sur la période précédente." : `${Math.abs(total - previousTotal)} activité(s) ${change > 0 ? "de plus" : change < 0 ? "de moins" : "de différence"} (${change > 0 ? "+" : ""}${change}%).`}</p></div><div className="mt-6"><div className="mb-3 flex items-center justify-between"><h3 className="font-black text-slate-900 dark:text-white">Activités réalisées</h3><span className="text-xs font-semibold text-slate-400">{total} au total</span></div>{sortedEntries.length ? <ul className="max-h-64 space-y-2 overflow-y-auto">{sortedEntries.map((entry, index) => <li key={`${entry.date}-${entry.activity || "legacy"}-${index}`} className="flex items-center justify-between gap-3 rounded-xl border border-slate-100 px-3 py-2.5 dark:border-slate-700"><div className="min-w-0"><p className="truncate text-sm font-semibold text-slate-700 dark:text-slate-200">{entry.activity || "Activité enregistrée (détail indisponible)"}</p><p className="text-xs capitalize text-slate-400">{new Date(`${entry.date}T00:00:00`).toLocaleDateString("fr-FR", { weekday: "long", day: "numeric", month: "long" })}</p></div><span className={`shrink-0 rounded-full px-2.5 py-1 text-[11px] font-bold ${entry.kind === "task" ? "bg-blue-50 text-blue-600" : entry.kind === "habit" ? "bg-emerald-50 text-emerald-600" : "bg-slate-100 text-slate-500"}`}>{entry.kind === "task" ? "Tâche" : entry.kind === "habit" ? "Habitude" : `×${entry.count}`}</span></li>)}</ul> : <div className="rounded-xl border border-dashed border-slate-300 p-6 text-center"><p className="font-bold text-slate-700 dark:text-slate-200">Aucune activité enregistrée sur cette période</p><p className="mt-1 text-sm text-slate-400">Les tâches et habitudes terminées apparaîtront ici avec leur date.</p></div>}</div></section></div>;
}
function ReportMetric({ label, value, detail, color }: { label: string; value: number; detail: string; color: string }) { const palette: Record<string, string> = { violet: "bg-violet-50 text-violet-600", blue: "bg-blue-50 text-blue-600", green: "bg-emerald-50 text-emerald-600", orange: "bg-orange-50 text-orange-600" }; return <div className="rounded-2xl border border-slate-100 p-3 dark:border-slate-700"><p className="text-[11px] font-bold text-slate-400">{label}</p><p className="mt-1 text-2xl font-black text-slate-900 dark:text-white">{value}</p><span className={`mt-2 inline-block rounded-full px-2 py-1 text-[10px] font-bold ${palette[color]}`}>{detail}</span></div>; }
type CurrentWeather = { temperature: number; apparentTemperature: number; humidity: number; code: number; time: string; place: string };
function weatherDescription(code: number) {
  if (code === 0) return "Ciel dégagé";
  if (code <= 2) return "Peu nuageux";
  if (code === 3) return "Couvert";
  if (code === 45 || code === 48) return "Brouillard";
  if ([51, 53, 55, 56, 57].includes(code)) return "Bruine";
  if ([61, 63, 65, 66, 67, 80, 81, 82].includes(code)) return "Pluie";
  if ([71, 73, 75, 77, 85, 86].includes(code)) return "Neige";
  if ([95, 96, 99].includes(code)) return "Orage";
  return "Conditions variables";
}
function WeatherCard() {
  const [weather, setWeather] = useState<CurrentWeather | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const loadWeather = () => {
    if (!navigator.geolocation) { setError("La géolocalisation n’est pas disponible dans ce navigateur."); return; }
    setLoading(true); setError("");
    navigator.geolocation.getCurrentPosition(async ({ coords }) => {
      try {
        const params = new URLSearchParams({ latitude: String(coords.latitude), longitude: String(coords.longitude), current: "temperature_2m,relative_humidity_2m,apparent_temperature,weather_code", timezone: "auto" });
        const placeParams = new URLSearchParams({ latitude: String(coords.latitude), longitude: String(coords.longitude), localityLanguage: "fr" });
        const [weatherResult, placeResult] = await Promise.allSettled([fetch(`https://api.open-meteo.com/v1/forecast?${params}`), fetch(`https://api.bigdatacloud.net/data/reverse-geocode-client?${placeParams}`)]);
        if (weatherResult.status === "rejected") throw weatherResult.reason;
        const response = weatherResult.value;
        if (!response.ok) throw new Error("Impossible de récupérer la météo pour le moment.");
        const placeData = placeResult.status === "fulfilled" && placeResult.value.ok ? await placeResult.value.json() as { city?: string; locality?: string; principalSubdivision?: string; countryName?: string } : null;
        const place = placeData ? [placeData.city || placeData.locality, placeData.principalSubdivision, placeData.countryName].filter(Boolean).join(", ") : "Votre position";
        const data = await response.json() as { current?: { temperature_2m: number; apparent_temperature: number; relative_humidity_2m: number; weather_code: number; time: string } };
        if (!data.current) throw new Error("Les données météo reçues sont incomplètes.");
        setWeather({ temperature: Math.round(data.current.temperature_2m), apparentTemperature: Math.round(data.current.apparent_temperature), humidity: data.current.relative_humidity_2m, code: data.current.weather_code, time: data.current.time, place });
      } catch (cause) { setError(cause instanceof Error ? cause.message : "Une erreur est survenue lors du chargement de la météo."); }
      finally { setLoading(false); }
    }, positionError => {
      setLoading(false);
      setError(positionError.code === positionError.PERMISSION_DENIED ? "Accès à la position refusé. Autorisez la localisation pour afficher la météo." : "Position introuvable. Vérifiez les réglages de localisation et réessayez.");
    }, { enableHighAccuracy: false, timeout: 10000, maximumAge: 300000 });
  };
  return <Card className="h-full"><div className="mb-3 flex items-center gap-2"><CloudSun className="text-blue-500" size={19}/><span className="text-xs font-bold text-slate-400">MÉTÉO LOCALE</span></div>{weather ? <><p className="mb-2 flex items-center gap-1.5 text-xs font-bold text-slate-500 dark:text-slate-300"><MapPin size={14} className="text-blue-500"/>{weather.place}</p><p className="text-3xl font-black text-slate-900 dark:text-white">{weather.temperature}°C <span className="text-sm font-semibold text-slate-400">{weatherDescription(weather.code)}</span></p><p className="mt-2 text-xs text-slate-400">Ressenti {weather.apparentTemperature}°C · Humidité {weather.humidity}%</p><p className="mt-1 text-xs text-slate-400">Mis à jour à {weather.time.slice(-5)}</p></> : <p className="min-h-12 text-sm text-slate-500 dark:text-slate-300">{error || (loading ? "Recherche de votre position…" : "Autorisez votre position pour afficher la météo locale.")}</p>}<button type="button" onClick={loadWeather} disabled={loading} className="mt-3 rounded-lg bg-blue-50 px-3 py-2 text-xs font-bold text-blue-600 transition hover:bg-blue-100 disabled:opacity-50">{loading ? "Chargement…" : weather ? "Actualiser" : "Utiliser ma position"}</button></Card>;
}
function Stat({ icon: Icon, label, value, detail, color }: { icon: React.ElementType; label: string; value: string; detail: string; color: string }) { const c: Record<string, string> = { violet: "bg-violet-50 text-violet-600", orange: "bg-orange-50 text-orange-600", blue: "bg-blue-50 text-blue-600", green: "bg-emerald-50 text-emerald-600" }; return <Card className="max-sm:px-3 max-sm:py-4"><div className="flex items-start justify-between gap-2"><div className="min-w-0"><p className="break-words text-xs font-semibold leading-tight text-slate-400 max-sm:text-[11px]">{label}</p><p className="mt-2 text-2xl font-black text-slate-900 dark:text-white max-sm:text-xl">{value}</p><p className="mt-1 break-words text-[11px] font-semibold leading-tight text-slate-400">{detail}</p></div><div className={`grid h-10 w-10 shrink-0 place-items-center rounded-xl max-sm:h-8 max-sm:w-8 ${c[color]}`}><Icon size={19}/></div></div></Card>; }
function Agenda({ time, title, tag, color }: { time: string; title: string; tag: string; color: "violet" | "orange" | "blue" }) { return <div className="flex items-center gap-3"><span className="w-10 text-xs font-bold text-slate-400">{time}</span><div className={`h-10 w-1 rounded-full ${color === "violet" ? "bg-violet-500" : color === "orange" ? "bg-orange-400" : "bg-blue-500"}`} /><div><p className="text-xs font-bold text-slate-700 dark:text-slate-200">{title}</p><p className="text-[11px] text-slate-400">{tag}</p></div></div>; }

